          }
        }
        minorRows.push(minorRow);
      }

      const minorMatrix = new Matrix(minorRows);
      const cofactor = Math.pow(-1, j) * this.get(0, j) * minorMatrix.determinant();
      det += cofactor;
    }

    return det;
  }

